package com.vandorlabs.vehicle;

import com.vandorlabs.physics.RigidTransform;
import java.util.*;
import net.minecraft.nbt.*;
import net.minecraft.util.math.BlockPos;

/** Epoch, saved-envelope retention and bounded pending admission; no simulated gameplay publisher. */
public final class VehicleBodyPoseStateChecks {
 private static int checks;private static void need(boolean value,String why){checks++;if(!value)throw new AssertionError("Body pose state: "+why);}
 private static List<VehicleBodyPoseFrame.Body> body(double roll){return Collections.singletonList(new VehicleBodyPoseFrame.Body(new BlockPos(3,4,5),RigidTransform.rotation(0,0,1,roll)));}
 private static NBTTagCompound saved(VehicleBodyPoseState state){NBTTagCompound out=new NBTTagCompound();state.write(out);return out;}
 public static void main(String[] args){
  VehicleBodyPoseState server=new VehicleBodyPoseState();need(!server.commit(0,Collections.emptyList()).present()&&saved(server).hasNoTags(),"ordinary state/save has no extra fields");VehicleBodyPoseFrame first=server.commit(51,body(20));need(first.epoch==1&&first.layout==51,"first accepted general generation");VehicleBodyPoseFrame moved=server.commit(51,body(21));need(moved.epoch==1,"pose motion does not increment layout generation");NBTTagCompound before=saved(server);boolean bad=false;try{server.commit(52,null);}catch(IllegalArgumentException expected){bad=true;}need(bad&&saved(server).equals(before),"failed preparation does not increment epoch or replace pose");VehicleBodyPoseFrame changed=server.commit(52,body(21));need(changed.epoch==2,"accepted layout change increments once");VehicleBodyPoseFrame clear=server.commit(0,Collections.emptyList());need(clear.reset()&&clear.epoch==3&&server.commit(0,Collections.emptyList()).epoch==3,"explicit reset increments once and remains durable");need(server.commit(51,body(22)).epoch==4,"return to general cannot reuse reset generation");
  VehicleBodyPoseState client=new VehicleBodyPoseState();int[] applied={0};VehicleBodyPoseState.Receiver receiver=(frame,local)->{applied[0]++;return true;};need(!client.receive(first,null,false)&&client.usesGeneral()&&!client.current().present(),"unmatched first source remains one pending frame");need(!client.receive(changed,null,false),"new source may replace pending frame");need(!client.receive(moved,receiver,false)&&applied[0]==0,"lower pending generation cannot resurrect old layout");need(client.applyPending(receiver,false)&&client.current()==changed&&applied[0]==1,"matching admitted source consumes latest pending frame");need(!client.receive(new VehicleBodyPoseFrame(2,53,body(23)),receiver,false)&&applied[0]==1,"same generation cannot identify another layout");need(!client.receive(VehicleBodyPoseFrame.NONE,receiver,false)&&client.current()==changed,"absent tail cannot clear general pose");need(client.receive(clear,receiver,false)&&!client.usesGeneral()&&client.current()==clear,"explicit newer reset retires general pose");need(!client.receive(changed,receiver,false)&&client.current()==clear,"late pre-reset generation cannot resurrect");
  NBTTagCompound original=first.writeNBT();VehicleBodyPoseState loaded=VehicleBodyPoseState.retain(original);original.setLong("Layout",999);loaded.readRetained();need(loaded.current().layout==51&&saved(loaded).getCompoundTag(VehicleBodyPoseFrame.NBT_KEY).equals(first.writeNBT()),"retained envelope owns exact input and does not mutate epoch on read");need(!loaded.applyPending((frame,local)->false,false)&&saved(loaded).getCompoundTag(VehicleBodyPoseFrame.NBT_KEY).equals(first.writeNBT()),"unmatched saved pose retains original envelope");need(loaded.applyPending(receiver,false)&&loaded.current().epoch==1,"loaded matching layout applies without committing a new generation");
  for(NBTBase malformed:new NBTBase[]{new NBTTagString("wrong type"),new NBTTagCompound()}){VehicleBodyPoseState retained=VehicleBodyPoseState.retain(malformed);boolean refused=false;try{retained.readRetained();}catch(IllegalArgumentException expected){refused=true;}need(refused&&saved(retained).getTag(VehicleBodyPoseFrame.NBT_KEY).equals(malformed),"failed saved envelope retained exactly and not installed");}
  NBTTagCompound future=first.writeNBT();future.setString("UnknownFuture","retain");VehicleBodyPoseState retained=VehicleBodyPoseState.retain(future);bad=false;try{retained.readRetained();}catch(IllegalArgumentException expected){bad=true;}need(bad&&saved(retained).getCompoundTag(VehicleBodyPoseFrame.NBT_KEY).equals(future),"unknown future envelope remains inert and exact");
  VehicleBodyPoseState resetLoaded=VehicleBodyPoseState.retain(clear.writeNBT());resetLoaded.readRetained();need(!resetLoaded.usesGeneral()&&resetLoaded.current().epoch==3,"saved explicit reset loads through ordinary legacy runtime");VehicleBodyPoseState max=VehicleBodyPoseState.retain(new VehicleBodyPoseFrame(Long.MAX_VALUE,51,body(0)).writeNBT());max.readRetained();NBTTagCompound maximum=saved(max);bad=false;try{max.commit(52,body(0));}catch(ArithmeticException expected){bad=true;}need(bad&&saved(max).equals(maximum),"epoch exhaustion never wraps or replaces original pose");
  System.out.println("Body pose generation PASS checks="+checks+" accepted commits only/legacy absence/one pending/latest epoch/reset/retained failures; actual entity load and runtime application separate");
 }
}
